// Pick the first listing link that is NOT already in the posted log.
const cfg = $('Config').first().json;
const html = String($('Fetch listing').first().json.data || '');

// Items arriving here = rows of the posted-log sheet
const logged = new Set();
for (const it of $input.all()) {
  const m = String(it.json.url || '').match(/\/(news-detail|article)\/(\d+)\//);
  if (m) logged.add(m[1] + ':' + m[2]);
}

const re = /href=["']((?:https?:\/\/(?:www\.)?placidway\.com)?\/(news-detail|article)\/(\d+)\/[^"'#?\s]+)["']/gi;
const seen = new Set();
const fresh = [];
let m;
while ((m = re.exec(html)) !== null) {
  const path = m[1].replace(/^https?:\/\/(?:www\.)?placidway\.com/i, '');
  const type = m[2] === 'news-detail' ? 'news' : 'article';
  const key = type + ':' + m[3];
  if (seen.has(key)) continue;
  seen.add(key);
  if (!logged.has(key)) fresh.push({ path, type, key });
}
if (!fresh.length) throw new Error('No fresh item: every link on the listing page is already in the log.');

const pick = fresh.find(f => f.type === cfg.PREFERRED_TYPE) || fresh[0];
return [{ json: { path: pick.path, content_type: pick.type, url: 'https://www.placidway.com' + pick.path } }];

// Turn the raw article HTML into clean source text (title, summary, body, image).
const html = String($input.first().json.data || '');
const pick = $('Pick first unposted').first().json;

const decode = s => String(s || '')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"')
  .replace(/&#0?39;|&rsquo;|&lsquo;/g, "'").replace(/&ldquo;|&rdquo;/g, '"')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)));
const meta = prop => {
  const a = new RegExp('<meta[^>]+(?:property|name)=["\']' + prop + '["\'][^>]*content=["\']([^"\']*)["\']', 'i').exec(html);
  if (a) return decode(a[1]);
  const b = new RegExp('<meta[^>]+content=["\']([^"\']*)["\'][^>]*(?:property|name)=["\']' + prop + '["\']', 'i').exec(html);
  return b ? decode(b[1]) : '';
};
const stripTags = s => decode(String(s || '').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();

let text = decode(html
  .replace(/<meta[^>]*>/gi, ' ')
  .replace(/<(script|style|noscript|svg|nav|header|footer|form)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<\/(p|div|h[1-6]|li|tr|section)>/gi, '\n')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<[^>]+>/g, ' '))
  .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
for (const stop of ['Request your Free Quote', 'Trusted Medical Tourism Platform', 'Unlock the Best']) {
  const i = text.indexOf(stop);
  if (i > 200) text = text.slice(0, i);
}

const title = (meta('og:title') || stripTags((/<h1[^>]*>([\s\S]*?)<\/h1>/i.exec(html) || [])[1]) ||
  stripTags((/<title[^>]*>([\s\S]*?)<\/title>/i.exec(html) || [])[1])).trim();
const summary = (meta('og:description') || meta('description')).trim();
if (!title || (text.length < 200 && !summary)) throw new Error('Extract: page had no usable title/body: ' + pick.url);

const body = text.slice(0, 4000);
let image_url = meta('og:image') || '';
if (image_url && !/^https?:\/\//i.test(image_url)) image_url = '';

return [{ json: {
  url: pick.url, content_type: pick.content_type, title, summary, image_url, body,
  source_text: 'SOURCE TITLE: ' + title + '\nSOURCE SUMMARY: ' + summary + '\nSOURCE BODY:\n' + body,
} }];

// Deterministic safety checks on the AI draft (no AI involved).
const src = $('Extract source').first().json;
const out = $input.first().json.output || {};

const hook = String(out.hook || '').trim();
const lines = (Array.isArray(out.value_lines) ? out.value_lines : []).map(s => String(s).trim()).filter(Boolean);
const cta = String(out.cta || '').trim();
const tags = (Array.isArray(out.hashtags) ? out.hashtags : [])
  .map(s => '#' + String(s).replace(/^#+/, '').replace(/[^\p{L}\p{N}_]/gu, '')).filter(t => t.length > 1);
const post_text = [hook, lines.join('\n'), cta, tags.join(' ')].filter(Boolean).join('\n\n');

const issues = [];
if (!hook) issues.push('missing hook');
if (lines.length < 2 || lines.length > 4) issues.push('value lines must be 2-4 (got ' + lines.length + ')');
if (!cta) issues.push('missing call to action');
if (tags.length < 3 || tags.length > 5) issues.push('hashtags must be 3-5 (got ' + tags.length + ')');
if (post_text.length > 450) issues.push('post is ' + post_text.length + ' chars (limit 450)');
if (/https?:\/\//i.test(post_text)) issues.push('post must not contain a URL');

const banned = /\b(cure[sd]?|guarantee[sd]?|guaranteeing|risk[- ]free|painless|miracle|permanent(?:ly)?|heal(?:s|ed|ing)?|no side effects|safe(?:st|ly)?|best (?:in the world|clinic|dentist|price)|will (?:restore|fix|transform|eliminate|improve))\b/i;
const b = banned.exec(post_text);
if (b) issues.push('banned medical/outcome wording: "' + b[0] + '"');

// Every number in the post must exist in the source
const sourceAll = (src.title + ' ' + src.summary + ' ' + src.body).replace(/,/g, '');
const nums = (post_text.replace(/#\S+/g, ' ').match(/\d[\d.,]*/g) || []).map(n => n.replace(/[.,]+$/, '').replace(/,/g, ''));
for (const n of nums) if (n && !sourceAll.includes(n)) issues.push('number/price not found in source: ' + n);

return [{ json: {
  url: src.url, title: src.title, content_type: src.content_type, image_url: src.image_url,
  post_text, post_chars: post_text.length, rule_pass: issues.length === 0, rule_issues: issues,
} }];

// One place that decides the final status row for every path.
const p = $('Rules check').first().json;
const cfg = $('Config').first().json;
const j = $input.first().json;

let status, details = '', fb = '';
if (p.rule_pass === false) {
  status = 'REJECTED_RULES'; details = (p.rule_issues || []).join('; ');
} else if (j.error) {
  status = 'FAILED_PUBLISH'; details = (j.error.message || j.error);
} else if (j.id || j.post_id) {
  status = 'PUBLISHED'; fb = j.post_id || j.id; details = 'page ' + cfg.FB_PAGE_ID;
} else if (j.data && j.data.approved === true) {
  status = 'SIMULATED'; details = 'Dry run: approved but not sent to Facebook';
} else {
  status = 'REJECTED_BY_REVIEWER'; details = 'Rejected, or no reply within 24h';
}

return [{ json: {
  date: new Date().toISOString(), content_type: p.content_type, title: p.title, url: p.url,
  post_text: p.post_text, fb_post_id: fb, status, details: String(details).slice(0, 500),
} }];
